INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429808, 16137, 'South China Morning Post', 'en', 'Warsh signals US Fed may need to raise rates if above-target inflation lingers', 'https://www.scmp.com/news/world/united-states-canada/article/3365658/warsh-says-us-fed-has-work-do-if-above-target-inflation-lingers', 'The US central bank will “have work to do” if policymakers are not confident that underlying inflation is returning to its 2 per cent target, Federal Reserve Chairman Kevin Warsh said on Friday in remarks that acknowledged financial conditions do not appear restrictive and marked the closest he has come to acknowledging interest rate hikes may be needed to ease price pressures. “Here is my standard: We must be confident that underlying inflation is moving to our objective, clearly and at...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/9f5a818e-052d-45df-8552-846f6481eee4_69a66665.jpg?itok=opFwdnr-&v=1787930004', '2026-08-28T15:13:26+00:00', '2026-08-29T00:09:28.522536'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429966, 16137, 'Euronews', 'en', 'Warsh flags inflation concerns as he rejects Fed forward guidance', 'http://www.euronews.com/business/2026/08/28/warsh-flags-inflation-concerns-as-he-rejects-fed-forward-guidance', 'Federal Reserve Chair Kevin Warsh used his first Jackson Hole address on Friday to argue that financial conditions are not restrictive and that underlying inflation has not meaningfully improved, a hawkish assessment that strengthens the case for a rate hike, while ruling out forward guidance.', '', '2026-08-28T15:16:47+00:00', '2026-08-29T00:09:56.325391'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
